_t=open('/home/claude/test/tform2.py').read(); exec(_t[:_t.index("with sync_playwright() as p:")])
import time
with sync_playwright() as p:
  b=p.chromium.launch()
  for vw,vh,mov,dev in ((390,844,True,'mov'),(1366,700,False,'pc')):
    sd=json.loads(json.dumps(seed())); T=sd['club/datos']['taller']; now=int(time.time()*1000)
    T['articulos'].append({'id':'grip','nombre':'Grip Yonex Super Grap','codigo':'G1','tipo':'Grip','esCordaje':False,'precio':3.5,'stock':5,'unidad':'unidades','proveedores':[]})
    T['articulos'].insert(0,{'id':'gz','nombre':'GRIP OLIVER COLORES · Verde','grupoId':'gO','grupoNombre':'GRIP OLIVER COLORES','color':'Verde','tipo':'Grip','esCordaje':False,'precio':2.5,'stock':4})
    T['articulos'].append({'id':'ga','nombre':'GRIP OLIVER COLORES · Amarillo','grupoId':'gO','grupoNombre':'GRIP OLIVER COLORES','color':'Amarillo','tipo':'Grip','esCordaje':False,'precio':2.5,'stock':9})
    T['articulos'].append({'id':'gx','nombre':'GRIP OLIVER COLORES · Rosa','grupoId':'gO','grupoNombre':'GRIP OLIVER COLORES','color':'Rosa','colorInactivo':True,'tipo':'Grip','esCordaje':False,'precio':2.5,'stock':2})
    T['pedidos']=[dict(T['pedidos'][0],id='pL',estado='terminado',pagado=False,precio=16,marcaModelo='Babolat n-limite',horaFin=now)]
    pg,errs=pagina(b,vw,vh,mov,sd,admin=True); dl=[]; pg.on('dialog',lambda d:(dl.append(d.message),d.accept()))
    pg.goto('https://test.local/app.html'); pg.wait_for_timeout(3000)
    pg.evaluate("document.querySelectorAll('button').forEach(b=>{if(b.textContent.trim()==='Saltar')b.click()})"); pg.wait_for_timeout(500)
    pg.evaluate("showSection('taller'); TallerApp.irATab('cola')"); pg.wait_for_timeout(800)
    pg.locator('.im-editar-lista').click(); pg.wait_for_timeout(500)
    ok(pg.locator('.im-ed-ad-sel').count()==1, f'{dev}: apartado «Otros artículos» en Editar')
    og=pg.evaluate("[...document.querySelectorAll('.im-ed-ad-sel optgroup')].map(g=>[g.label,[...g.children].map(o=>o.textContent.split(' · ')[1])])"); print(dev,og)
    ok(og==[['GRIP OLIVER COLORES (2 colores)',['Amarillo','Verde']]], f'{dev}: los colores del grip salen juntos (y el desactivado no)')
    pg.locator('.im-ed-ad-sel').select_option('grip'); pg.locator('.im-ed-ad-cant').fill('2'); pg.locator('.im-ed-ad-anadir').click(); pg.wait_for_timeout(300)
    ok(pg.input_value('#imEdPrecio')=='23' and '2 × Grip' in pg.inner_text('.im-ed-ads'), f'{dev}: añade 2 grips y el precio sube a 23 € ({pg.input_value("#imEdPrecio")})')
    pg.locator('.im-ed-ads').scroll_into_view_if_needed(); pg.screenshot(path=SP+f'artsed_{dev}.png')
    pg.locator('#tallerModalRoot button', has_text='Guardar cambios').click(); pg.wait_for_timeout(600)
    st=pg.evaluate("(()=>{const s=TallerApp.getState();const p=s.pedidos[0];return [p.precio,p.articulosAdicionales.map(i=>[i.articuloId,i.cantidad,i.precioUnitario]),s.articulos.find(a=>a.id==='grip').stock]})()")
    ok(st==[23,[['grip',2,3.5]],3], f'{dev}: se guarda en el pedido y descuenta 2 del stock {st}')
    ok(any('Artículos: ninguno → 2 × Grip' in x for x in dl), f'{dev}: la confirmación indica el artículo añadido')
    pg.locator('.im-editar-lista').click(); pg.wait_for_timeout(400)
    pg.locator('.im-ed-ad-quitar').click(); pg.wait_for_timeout(200)
    ok(pg.input_value('#imEdPrecio')=='16', f'{dev}: al quitarlo el precio vuelve a 16 €')
    pg.locator('#tallerModalRoot button', has_text='Guardar cambios').click(); pg.wait_for_timeout(500)
    st=pg.evaluate("(()=>{const s=TallerApp.getState();const p=s.pedidos[0];return [p.precio,p.articulosAdicionales.length,s.articulos.find(a=>a.id==='grip').stock]})()")
    ok(st==[16,0,5], f'{dev}: quitar devuelve el stock {st}')
    ok(not [e for e in errs if 'hasPending' not in e], f'{dev}: sin errores {errs}'); pg.close()
  b.close()
print('TOTAL',sum(R),'/',len(R))
